import type { QuranAyah, SurahBundle } from '../../types';

import {
  GENERATED_CORPUS_READY,
  GENERATED_CORPUS_SOURCE,
  GENERATED_SURAHS,
  GENERATED_SURAH_COUNT,
  GENERATED_SURAH_NUMBERS,
  loadGeneratedSurah,
} from './generated/registry';

export { GENERATED_CORPUS_READY, GENERATED_CORPUS_SOURCE, GENERATED_SURAH_COUNT };

/**
 * Bundled Quran corpus — the only source of Arabic Quran text in the app.
 *
 * Generated by `cd api && npm run quran:build` from the pinned Tanzil.net Uthmani
 * v1.1 text and verified verse by verse by `npm run quran:validate`, which also
 * runs before every Metro bundle (see metro.config.js). Never edit the JSON files.
 *
 * This is a lazy view: reading `BUNDLED_SURAHS[n]` loads only surah n.
 */
export const BUNDLED_SURAHS: Record<number, SurahBundle> = GENERATED_SURAHS;

/** Surah numbers present in the bundle, without loading any text. */
export const BUNDLED_SURAH_NUMBERS: readonly number[] = GENERATED_SURAH_NUMBERS;

/** @deprecated Hand-typed ayahs were removed; all text comes from BUNDLED_SURAHS. */
export const BUNDLED_STANDALONE_AYAHS: QuranAyah[] = [];

export function isGeneratedCorpusReady(): boolean {
  return GENERATED_CORPUS_READY && GENERATED_SURAH_COUNT === 114;
}

export function getBundledSurah(number: number): SurahBundle | undefined {
  const bundle = loadGeneratedSurah(number);
  return bundle?.ayahs?.length ? bundle : undefined;
}
